#!/opt/homebrew/bin/bash
# leaf uplinks (leaf = LLDP neighbour; the fake puts rail A on leaf1, rail B on leaf2). The log lines are units in 60
# (ff_uplink), the FF wiring and metadata keys are checked on golden-B (50); the dashboard card here parses stored
# archives (fixtures/bundles/14_*, tools/mkbundles.sh; 10-26)
# tier: fast
# checks: 46
# secs: 14
source "$(dirname "${BASH_SOURCE[0]}")/../lib.sh" "$@"
X=$S/fixtures/bundles

python3 $P $X/14_ua.tgz $W/ua.html > $W/p.out 2>&1
nodes() { grep '^    var topoNodesData = ' "$1" | sed 's/^    var topoNodesData = //; s/;$//'; }
edges() { grep '^    var topoEdgesData = ' "$1" | sed 's/^    var topoEdgesData = //; s/;$//'; }
# an uplink edge carries the verdict twice: in its tooltip and in its panel (the drawer a tap opens)
chk "dashboard uplink card: verdict (a), once per leaf row in the card (2) plus once per 'Where to look' line (2) = 4 in the page text, and on each uplink edge's tooltip and panel on the map (1 spine x 2 leaves = 2 edges)" "grep -q 'Leaf uplinks, declared by the run: 1 spines x 1 links x 300G = 300.0 G per leaf' $W/ua.html && [ \$(grep -v '^    var topoEdgesData' $W/ua.html | grep -o 'at declared uplink capacity: oversubscribed 2.7:1 by design' | wc -l) -eq 4 ] && [ \$(grep -o '<ul class=\"where-list mb-0\">.*' $W/ua.html | head -n 1 | sed 's#</ul>.*##' | grep -o 'oversubscribed 2.7:1 by design' | wc -l) -eq 2 ] && [ \$(edges $W/ua.html | jq '[.[] | select(.uplink == true and (.title | test(\"at declared uplink capacity: oversubscribed 2.7:1 by design\")) and (.panel.verdict | test(\"oversubscribed 2.7:1 by design\")))] | length') -eq 2 ] && [ \$(edges $W/ua.html | jq '[.[] | select(.uplink == true)] | length') -eq 2 ] && [ \"\$(hrows $W/ua.html)\" = '{\"SLOW(cross)\":2,\"OK\":2}' ]"
python3 $P $X/14_ub.tgz $W/ub.html > $W/p.out 2>&1
python3 $P $X/14_un.tgz $W/un.html > $W/p.out 2>&1   # nothing declared (the topology checks below)
chk "dashboard uplink card: verdict (b), once per leaf row (2) plus once per 'Where to look' line (2) = 4 in the page text, and on each uplink edge's tooltip and panel (2 spines x 2 leaves = 4 edges)" "[ \$(grep -v '^    var topoEdgesData' $W/ub.html | grep -o 'uplinks carried only 6% of declared capacity' | wc -l) -eq 4 ] && [ \$(grep -o '<ul class=\"where-list mb-0\">.*' $W/ub.html | head -n 1 | sed 's#</ul>.*##' | grep -o 'uplinks carried only 6% of declared capacity' | wc -l) -eq 2 ] && [ \$(edges $W/ub.html | jq '[.[] | select(.uplink == true and (.title | test(\"uplinks carried only 6% of declared capacity\")) and (.panel.verdict | test(\"carried only 6% of declared capacity\")))] | length') -eq 4 ] && [ \$(edges $W/ub.html | jq '[.[] | select(.uplink == true)] | length') -eq 4 ]"
# every card sits in a tab (10-28 23:05): above the nav-tabs line only the "Where to look" card and the problems
# banner (two card-headers, no table); the uplink card is in the Topology pane; the tab list is in order, Temperatures
# and Run checks carrying counts
nav=$(grep -n 'class="nav nav-tabs' $W/ub.html | cut -d: -f1)
inpane() { awk -v id="$2" -v pat="$3" '/class="tab-pane/ { inp = index($0, "id=\"" id "\"") > 0 } inp && index($0, pat) { n++ } END { print n + 0 }' "$1"; }
chk "dashboard tabs: above the nav-tabs line 2 card-headers (Where to look, then the problems banner, in that order) and 0 tables; the uplink card's header in no pane (A5: the drawer sits outside the panes), 1 on the whole page" \
    "[ -n \"$nav\" ] && [ \$(awk -v n=$nav 'NR < n' $W/ub.html | grep -c 'class=\"card-header') = 2 ] && [ \"\$(awk -v n=$nav 'NR < n' $W/ub.html | grep -o 'card-header\"[^>]*>[^<]*<b>Where to look first\\|card-header\"[^>]*>INCOMPLETE RESULT' | sed 's/.*<b>//; s/.*>//' | cut -c1-5 | tr '\n' ' ')\" = 'Where INCOM ' ] && [ \$(awk -v n=$nav 'NR < n' $W/ub.html | grep -c '<table') = 0 ] && [ \$(inpane $W/ub.html tab-topology 'Leaf uplinks, declared by the run') = 0 ] && [ \$(inpane $W/ub.html tab-nic 'Leaf uplinks, declared by the run') = 0 ] && [ \$(grep -c 'Leaf uplinks, declared by the run' $W/ub.html) = 1 ] && [ \$(inpane $W/ub.html tab-topology 'id=\"topoNetwork\"') = 1 ]" \
    "nav line $nav; above: $(awk -v n=$nav 'NR < n' $W/ub.html | grep -o 'card-header">[^<]*' | head -n 3)"
# the Topology map draws the declared spines and judges each leaf's uplinks as the card does (10-28 23:05); nothing
# sits below the map (the uplinks card is a drawer, the operator 23:56); the 2-leaf rule: with two leaves the fault cannot be
# placed, so the uplink edges go amber dashed "?" and the verdict says so
chk "topology (14_ub, 2 spines declared, 2 leaves): spine nodes Spine 1 and Spine 2; 4 uplink edges, each leaf to both spines, every one uplink: true, amber (#ffc107), dashed, labelled ?; no other edge carries uplink" \
    "[ \"\$(nodes $W/ub.html | jq -c '[.[] | select(.group == \"spine\") | .label]')\" = '[\"Spine 1\",\"Spine 2\"]' ] && [ \"\$(edges $W/ub.html | jq -c '[.[] | select(.uplink == true) | [.from, .to, .color.color, .label, (.dashes | type)]] | sort')\" = '[[\"leaf1.example\",\"spine1\",\"#ffc107\",\"?\",\"array\"],[\"leaf1.example\",\"spine2\",\"#ffc107\",\"?\",\"array\"],[\"leaf2.example\",\"spine1\",\"#ffc107\",\"?\",\"array\"],[\"leaf2.example\",\"spine2\",\"#ffc107\",\"?\",\"array\"]]' ] && [ \$(edges $W/ub.html | jq '[.[] | select(has(\"uplink\") and .uplink != true)] | length') = 0 ]" \
    "$(edges $W/ub.html | jq -c '[.[] | select(.uplink == true) | [.from, .to, .color.color, .label]]')"
chk "topology (14_ub): the card's verdict and the edge tooltips name the ambiguity ('this rail has two leaves: the runs cannot pick the leaf or the spine; read the switches' uplink port counters'), once per leaf row (2) plus once per 'Where to look' line (2) = 4 in the page text, and on all 4 edges" \
    "[ \$(grep -o 'this rail has two leaves: the runs cannot pick the leaf or the spine; read the switches&#x27; uplink port counters' $W/ub.html | wc -l | tr -d ' ') = 4 ] && [ \$(grep -o '<ul class=\"where-list mb-0\">.*' $W/ub.html | head -n 1 | sed 's#</ul>.*##' | grep -o 'cannot pick the leaf or the spine' | wc -l) -eq 2 ] && [ \$(edges $W/ub.html | jq '[.[] | select(.uplink == true and (.title | test(\"cannot pick the leaf or the spine\")))] | length') = 4 ]" \
    "$(grep -o 'cannot pick the leaf[^<]*' $W/ub.html | head -n 2)"
chk "topology control: the host links are untouched: 4 non-uplink edges on 14_ub, each with name, ip and a numeric gbps (the legend, the exclude list and the speed filter read those fields: edgeSpeed returns e.gbps once, 0 e.title.match / e.title.split), topoEdgesData differs between 14_ub and 14_un (byte-identical before, 10-28)" \
    "[ \"\$(edges $W/ub.html | jq -c '[.[] | select(.uplink != true) | [.name, .ip, (.gbps | type)]] | sort')\" = '[[\"h21 enp196s0np0\",\"198.19.2.21\",\"number\"],[\"h21 enp5s0np0\",\"198.19.1.21\",\"number\"],[\"h22 enp196s0np0\",\"198.19.2.22\",\"number\"],[\"h22 enp5s0np0\",\"198.19.1.22\",\"number\"]]' ] && [ \$(grep -c \"return typeof e.gbps === 'number' ? e.gbps : 999;\" $W/ub.html) = 1 ] && [ \$(grep -c 'e.title.match\\|e.title.split' $W/ub.html) = 0 ] && [ \$(edges $W/ub.html | jq '[.[] | select(.uplink == true)] | length') = 4 ] && ! cmp -s <(edges $W/ub.html) <(edges $W/un.html)" \
    "$(edges $W/ub.html | jq -c '[.[] | select(.uplink != true) | [.name, .ip, .gbps]]')"
chk "topology (14_un, nothing declared): one spine node 'Spine (not declared)', its tooltip asks for FF_SPINES; each leaf's uplink edge green with the measured out/in in its tooltip" \
    "[ \"\$(nodes $W/un.html | jq -c '[.[] | select(.group == \"spine\") | .label]')\" = '[\"Spine (not declared)\"]' ] && nodes $W/un.html | jq -e '.[] | select(.group == \"spine\") | select(.title | test(\"set FF_SPINES, FF_SPINE_LINKS and FF_SPINE_GBPS\"))' > $W/un_spine.jq && [ \"\$(edges $W/un.html | jq -c '[.[] | select(.uplink == true) | [.from, .color.color, (.title | test(\"out 240.0 G / in 240.0 G measured\"))]] | sort')\" = '[[\"leaf1.example\",\"#4ecca3\",true],[\"leaf2.example\",\"#4ecca3\",true]]' ]" \
    "$(edges $W/un.html | jq -c '[.[] | select(.uplink == true) | .title]')"
mkdir -p $W/gcsrc && cp -R $S/fixtures/golden-C $W/gcsrc/dp_validation_goldenC && tar -czf $W/gc.tgz -C $W/gcsrc dp_validation_goldenC
FF_SPINES=2 FF_SPINE_LINKS=2 FF_SPINE_GBPS=400 FF_CLIENT_SPINE_LINKS=1 FF_CLIENT_SPINE_GBPS=400 python3 $P $W/gc.tgz $W/gc.html > $W/p.out 2>&1
chk "topology (golden-C with 2 x 2 x 400G backend and 2 x 1 x 400G client uplinks declared at render time): the client leaf cleaf1 linked to both spines with 'declared 1 links x 400G', the backend leaves with 'declared 2 links x 400G'" \
    "[ \"\$(edges $W/gc.html | jq -c '[.[] | select(.uplink == true) | [.from, .to, (.title | capture(\"declared (?<d>[0-9]+ links x [0-9]+G)\") | .d)]] | sort')\" = '[[\"cleaf1.example\",\"spine1\",\"1 links x 400G\"],[\"cleaf1.example\",\"spine2\",\"1 links x 400G\"],[\"leaf1.example\",\"spine1\",\"2 links x 400G\"],[\"leaf1.example\",\"spine2\",\"2 links x 400G\"],[\"leaf2.example\",\"spine1\",\"2 links x 400G\"],[\"leaf2.example\",\"spine2\",\"2 links x 400G\"]]' ]" \
    "$(edges $W/gc.html | jq -c '[.[] | select(.uplink == true) | [.from, .to, .title]]' | cut -c1-400)"
# the Run checks count (10-29 00:28): cards with a flagged result; control 12_old_v2_allAtoB (preflight 0 findings,
# no UDP card) shows no number; golden-C (3 preflight findings + UDP beyond expected, rendered above) shows 2
python3 $P $X/12_old_v2_allAtoB.tar.gz $W/v2.html > $W/p.out 2>&1
chk "Run checks label: 14_ub 'Run checks (<span class=\"stat-bad\">1</span>)' (UDP beyond expected 40, preflight 0 findings); control 12_old_v2_allAtoB 'Run checks' with no number (preflight 0 findings, no UDP card, tab still present); golden-C 2 (3 preflight findings + UDP beyond)" \
    "grep -q '>Run checks (<span class=\"stat-bad\">1</span>)' $W/ub.html && grep -q 'stat-good\">0</b> findings' $W/ub.html && grep -q 'likely fabric) 40<' $W/ub.html && grep -q '>Run checks' $W/v2.html && [ \$(grep -c 'Run checks (' $W/v2.html) = 0 ] && grep -q 'stat-good\">0</b> findings' $W/v2.html && [ \$(grep -c 'UDP, no rate cap' $W/v2.html) = 0 ] && grep -q '>Run checks (<span class=\"stat-bad\">2</span>)' $W/gc.html && grep -q 'stat-bad\">3</b> findings' $W/gc.html" \
    "$(grep -o '>Run checks[^<]*<[^<]*<[^<]*' $W/ub.html $W/v2.html $W/gc.html | sed "s#$W/##" | tr '\n' ' ')"
chk "topology pane: after #topoNetwork only the toast and the legend (ids topoToast, topoLegend, topoLegendDetail) to the pane's end; the uplinks drawer (#topoUplinks, A5) sits outside the panes: after '<!-- container -->' and before the scripts that follow it (order: container end < drawer < next <script), 0 drawers inside a pane; the uplinks card-header once inside the offcanvas; no inline height:700px (control: min-height:420px once); the Uplinks toolbar button" \
    "[ \"\$(awk '/id=\"topoNetwork\"/ {o = 1; next} /id=\"topoUplinks\"|class=\"tab-pane|<!-- container -->/ {o = 0} o && /<div id=/' $W/ub.html | grep -o 'id=\"[a-zA-Z]*\"' | tr '\n' ' ')\" = 'id=\"topoToast\" id=\"topoLegend\" id=\"topoLegendDetail\" ' ] && ce=\$(grep -n '<!-- container -->' $W/ub.html | head -n 1 | cut -d: -f1) && dr=\$(grep -n 'id=\"topoUplinks\"' $W/ub.html | head -n 1 | cut -d: -f1) && sc=\$(awk -v c=\$ce 'NR > c && /<script/ {print NR; exit}' $W/ub.html) && [ \$ce -lt \$dr ] && [ \$dr -lt \$sc ] && [ \$(awk '/class=\"tab-pane/ {p = 1} /<!-- container -->/ {p = 0} p && /id=\"topoUplinks\"/ {n++} END {print n + 0}' $W/ub.html) = 0 ] && [ \$(awk '/id=\"topoUplinks\"/ {o = 1} /class=\"tab-pane/ {o = 0} o && /card-header\">Leaf uplink/ {n++} END {print n + 0}' $W/ub.html) = 1 ] && [ \$(grep -c 'height:700px' $W/ub.html) = 0 ] && [ \$(grep -c 'min-height:420px' $W/ub.html) = 1 ] && grep -q 'onclick=\"topoShowPanel('\"'\"'uplinks'\"'\"')\">Uplinks</button>' $W/ub.html" \
    "$(awk '/id="topoNetwork"/ {o = 1; next} /id="topoUplinks"/ {o = 0} o && /<div id=/' $W/ub.html | grep -o 'id="[a-zA-Z]*"' | tr '\n' ' ')"
# the Radial layout is run by the browser (QA's node probe and screenshots); the page can only show the placement
# code: the spine ring's half-step offset, the arcs sized by host count (10-29 01:29: "Sometimes there may be
# thousands of clients"), overflow rings, hidden labels, bonds one radius per host ring
chk "topology Radial placement code: the spine ring offset by half a spine step once; the constants R_HOST = 680, RING = 46, MINGAP = 22, LABELW = 90, GAP = 0.04 once; a group's floor min(hosts, 12) * MINGAP / R_HOST, its arc capped at what its hosts need (label width or host spacing) and, for a multi-leaf group, at 0.84 of its leaves' span; each group centred on its preferred angle, overlapping neighbours pushed apart equally; the floors scaled when many groups exceed the circle, once each; one DataSet update for the whole placement and one getIds for the legend; Radial places nodes with fixed: false so they stay draggable (the only fixed: true left is dragEnd's pin, skipped for a carried node); hosts at R_HOST + ring * RING on g.mid + turn - g.arc / 2 + g.arc * (k + 0.5) / cnt; labels hidden below LABELW unless hot; bonds at R_HOST - 70 - (ring % 9) * 26; physics off for radial; controls: the old sector width (0.84 * sector) and circular-mean centre (Math.atan2(sy, sx)) are gone (0 each)" \
    "[ \$(grep -c 'pin(n, sp.length > 1 ? 90 : 0, -Math.PI / 2 + Math.PI / sp.length + 2 \\* Math.PI \\* i / sp.length)' $W/ub.html) = 1 ] && [ \$(grep -c 'var R_HOST = 680, RING = 46, MINGAP = 22, LABELW = 90, GAP = 0.04;' $W/ub.html) = 1 ] && [ \$(grep -c 'g.floor = Math.min(g.hosts.length, 12) \\* MINGAP / R_HOST' $W/ub.html) = 1 ] && [ \$(grep -c 'g.arc = Math.min(share, (share \\* R_HOST / n >= LABELW ? LABELW : MINGAP) \\* n / R_HOST, g.span ? 0.84 \\* g.span : Infinity);' $W/ub.html) = 1 ] && [ \$(grep -c 'g.mid = (g.pref + 2 \\* Math.PI) % (2 \\* Math.PI);' $W/ub.html) = 1 ] && [ \$(grep -c 'if (d < need - 1e-9) { var push = (need - d) / 2; a.mid -= push; b.mid += push; moved = true; }' $W/ub.html) = 1 ] && [ \$(grep -c 'topoNodes.update(placed.concat(relabel));' $W/ub.html) = 1 ] && [ \$(grep -c 'placed.push({ id: n.id, x: r \\* Math.cos(a), y: r \\* Math.sin(a), fixed: false });' $W/ub.html) = 1 ] && [ \$(grep -c 'fixed: { x: true, y: true }' $W/ub.html) = 0 ] && [ \$(grep -cF 'fixed: id === topoDropped || id === topoCarried ? false : { x: true, y: true }' $W/ub.html) = 1 ] &&[ \$(grep -c 'var edgeIdList = topoEdges.getIds();' $W/ub.html) = 1 ] &&[ \$(grep -c 'if (fsum > room) gl.forEach(function(g) { g.floor \\*= room / fsum; });' $W/ub.html) = 1 ] &&[ \$(grep -c 'pin(n, R_HOST + ring \\* RING, g.mid - g.arc / 2 + g.arc \\* (k + 0.5) / cnt)' $W/ub.html) = 1 ] &&grep -q 'var labels = g.arc \\* R_HOST / m >= LABELW;' $W/ub.html && grep -q 'if (!labels && !n.hot && !(n.id in topoRadialLabels))' $W/ub.html && grep -q 'bondR\\[n.id\\] = R_HOST - 70 - (ringOf\\[n.host\\] % 9) \\* 26;' $W/ub.html && grep -q 'radial: {   // fixed rings, no physics' $W/ub.html && [ \$(grep -c '0.84 \\* sector' $W/ub.html) = 0 ] && [ \$(grep -c 'Math.atan2(sy, sx)' $W/ub.html) = 0 ]" \
    "$(grep -o 'pin(n, [^;]*' $W/ub.html | head -n 4)"
# Radial is the map's opening layout (10-29 01:54 "Make Radial the default"): one Python line sets it, the Radial
# button is active on load and the rings are placed at the first draw; above 400 nodes only Radial is offered (the operator
# 01:45: Hierarchical may stall with thousands of clients); Reset puts the map back as it opened (the operator 01:55)
chk "topology default layout: topoCurrentLayout = 'radial' once, the Radial button carries the active class and Hierarchical/Force do not, the first draw runs topoLayoutLimit() then topoSetLayout(topoCurrentLayout); TOPO_BIG = 400 once with the limit disabling tBtnHier/tBtnForce and the title 'Radial only above'; control: hosts and clients carry a boolean hot field" \
    "[ \$(grep -c \"var topoCurrentLayout = 'radial';\" $W/ub.html) = 1 ] && grep -q 'class=\"btn btn-outline-light active\" id=\"tBtnRadial\"' $W/ub.html && grep -q 'class=\"btn btn-outline-light\" id=\"tBtnHier\"' $W/ub.html && grep -q 'class=\"btn btn-outline-light\" id=\"tBtnForce\"' $W/ub.html && grep -q 'topoInit(); topoInitialized = true; topoLayoutLimit(); topoSetLayout(topoCurrentLayout);' $W/ub.html && [ \$(grep -c 'var TOPO_BIG = 400;' $W/ub.html) = 1 ] && grep -q \"\\[\\['tBtnHier', 'hierarchical'\\], \\['tBtnForce', 'force'\\]\\]\" $W/ub.html && grep -q \"el.title = big ? 'Radial only above ' + TOPO_BIG + ' nodes\" $W/ub.html && [ \"\$(nodes $W/ub.html | jq -c '[.[] | select(.group == \"host\" or .group == \"client\") | (.hot | type)] | unique')\" = '[\"boolean\"]' ]" \
    "$(grep -o 'class=\"btn btn-outline-light[^\"]*\" id=\"tBtn[A-Za-z]*\"' $W/ub.html | tr '\n' ' ')"
chk "topology Reset: resetTopo's body closes the panel (topoHidePanel), clears the selection (unselectAll), returns to the opening layout (topoSetLayout('radial')) and says so (topoToast('Map reset')); the toast element exists once; Reset no longer keeps the current layout (0 topoSetLayout(topoCurrentLayout) in the reset body)" \
    "body=\$(awk '/window.resetTopo = function/ {o = 1} o {print} o && /^    };/ {exit}' $W/ub.html) && [ \$(grep -c 'topoHidePanel();' <<<\"\$body\") = 1 ] && [ \$(grep -c 'topoNetwork.unselectAll();' <<<\"\$body\") = 2 ] && [ \$(grep -c \"topoSetLayout('radial');\" <<<\"\$body\") = 1 ] && [ \$(grep -c \"topoToast('Map reset');\" <<<\"\$body\") = 1 ] && [ \$(grep -c 'topoSetLayout(topoCurrentLayout)' <<<\"\$body\") = 0 ] && [ \$(grep -c 'id=\"topoToast\"' $W/ub.html) = 1 ] && grep -q 'function topoToast(msg)' $W/ub.html" \
    "$(awk '/window.resetTopo = function/ {o = 1} o {print} o && /^    };/ {exit}' $W/ub.html | grep -o 'topo[A-Za-z]*([^)]*)' | tr '\n' ' ')"
# 3b (the operator's hand acceptance of QA's demo, 10-29 01:20-01:38): a tap waits 250 ms (a double click opens nothing),
# then opens the node's or link's panel or closes it; a double click puts a node back unpinned; a press on a pinned
# node turns the view pan off and, once the pointer leaves the node's box, unpins and carries it; no vis 'hold'
chk "map gestures (3b): TOPO_CLICKWAIT = 250 with the click handler starting the timer once, a node tap opening topoShowPanel('node'), a blank tap topoHidePanel; one doubleClick handler cancelling the timer and putting the node back (topoUnpin + toast 'back in place'); a capture-phase pointerdown on the map container turning dragView off for a press on a pinned node, pointermove unpinning and carrying it (toast 'Unpinned <node>: release to drop'), dragEnd pinning unless the node was carried; 0 on('hold' (control: on('click', on('doubleClick', on('dragEnd' once each)" \
    "[ \$(grep -cF 'var TOPO_CLICKWAIT = 250, topoClickTimer = null;' $W/ub.html) = 1 ] && [ \$(grep -cF 'topoClickTimer = setTimeout(function() {' $W/ub.html) = 1 ] && grep -qF \"if (p.nodes.length > 0) topoShowPanel('node', p.nodes[0]);\" $W/ub.html && [ \$(grep -cF 'else topoHidePanel();' $W/ub.html) = 1 ] && [ \$(grep -cF \"topoNetwork.on('doubleClick', function(p) {\" $W/ub.html) = 1 ] && grep -qF \"topoUnpin([id]); topoToast(topoNameOf(id) + ' back in place');\" $W/ub.html && grep -qF \"topoContainer.addEventListener('pointerdown', function(e) {\" $W/ub.html && grep -qF 'if (topoPress !== null) topoNetwork.setOptions({ interaction: { dragView: false } });' $W/ub.html && grep -qF \"topoToast('Unpinned ' + topoNameOf(topoCarried) + ': release to drop');\" $W/ub.html && grep -qF \"window.addEventListener('pointermove', function(e) {\" $W/ub.html && [ \$(grep -cF \"on('hold'\" $W/ub.html) = 0 ] && [ \$(grep -cF \"on('click'\" $W/ub.html) = 1 ] && [ \$(grep -cF \"on('doubleClick'\" $W/ub.html) = 1 ] && [ \$(grep -cF \"on('dragEnd'\" $W/ub.html) = 1 ]" \
