# (A3: one <ul class="where-list"> of <li> lines; the where-top / where-rest split is gone)
wlines() { grep -o '<ul class="where-list mb-0">.*' "$1" | head -n 1 | sed 's#</ul>.*##; s#</li>#\n#g' | grep 'where-sev'; }
wn() { wlines "$1" | grep -c ''; }
chk "where to look (14_ub, 14_un, golden-C): the card (class 'card mb-3 where') sits before the INCOMPLETE banner where there is one; its header reads 'Where to look first' then '<N> findings, heat and slowness on the same host first' with N = its <li> lines in one <ul class=\"where-list mb-0\"> = 6 / 4 / 8 (0 where-top / where-rest left; control: a page with the chips removed counts 0 lines)" \
    "[ \$(grep -n 'card mb-3 where' $W/ub.html | head -n 1 | cut -d: -f1) -lt \$(grep -n 'INCOMPLETE RESULT' $W/ub.html | head -n 1 | cut -d: -f1) ] && ( for p in ub:6 un:4 gc:8; do f=$W/\${p%%:*}.html; n=\${p#*:}; grep -q \"<b>Where to look first</b> <span[^>]*>\$n findings, heat and slowness on the same host first</span>\" \$f && [ \$(wn \$f) = \$n ] && [ \$(grep -c '<ul class=\"where-list mb-0\">' \$f) = 1 ] && [ \$(grep -o '<ul class=\"where-list mb-0\">.*' \$f | head -n 1 | sed 's#</ul>.*##' | grep -o '<li>' | wc -l) = \$n ] && [ \$(grep -c 'where-top\\|where-rest' \$f) = 0 ] || exit 1; done ) && [ \$(sed 's/where-sev/x/g' $W/ub.html | wlines /dev/stdin | grep -c '') = 0 ]" \
    "ub $(wn $W/ub.html) un $(wn $W/un.html) gc $(wn $W/gc.html); $(grep -o '<b>Where to look first</b>[^<]*<span[^>]*>[^<]*' $W/ub.html | sed 's/<[^>]*>//g')"
chk "where to look, every line (3 pages, 18 lines): the 'open →' link (class where-go) comes FIRST, before the severity chip and the text; data-go decodes to JSON with a tab, node or link key; severities non-decreasing down the card (golden-C: 2 LOOK then 6 NOTE, 14_ub 6 LOOK); control: a reversed sample line fails the same order test" \
    "( for f in $W/ub.html $W/un.html $W/gc.html; do wlines \$f | while IFS= read -r l; do [ \$(awk -v s=\"\$l\" 'BEGIN { g = index(s, \"class=\\\"where-go\\\"\"); c = index(s, \"class=\\\"where-sev\"); t = index(s, \"class=\\\"where-text\\\"\"); exit !(g && c && t && g < c && c < t) }'; echo \$?) = 0 ] || exit 1; sed -E 's/.*data-go=\"([^\"]*)\".*/\\1/; s/&quot;/\"/g' <<<\"\$l\" | jq -e 'has(\"tab\") or has(\"node\") or has(\"link\")' > $W/wgo.out || exit 1; done || exit 1; [ \"\$(wlines \$f | grep -o 'where-sev s[0-9]' | sed 's/.*s//' | tr -d '\n')\" = \"\$(wlines \$f | grep -o 'where-sev s[0-9]' | sed 's/.*s//' | sort | tr -d '\n')\" ] || exit 1; done ) && [ \"\$(wlines $W/gc.html | grep -o 'where-sev s[0-9]' | sort | uniq -c | awk '{printf \"%s:%s \", \$1, \$3}')\" = '2:s1 6:s2 ' ] && ! awk -v s='<span class=\"where-sev s1\">LOOK</span> <span class=\"where-text\">x</span> <a class=\"where-go\">open</a>' 'BEGIN { g = index(s, \"class=\\\"where-go\\\"\"); c = index(s, \"class=\\\"where-sev\"); t = index(s, \"class=\\\"where-text\\\"\"); exit !(g && c && t && g < c && c < t) }'" \
    "$(wlines $W/gc.html | grep -o 'where-sev s[0-9]' | sed 's/.*s//' | tr -d '\n') | first ub line: $(wlines $W/ub.html | head -n 1 | cut -c1-120)"
# tab dots (criterion 3): a coloured dot after each judged tab's label (red #e94560 = a fault, amber #ffc107 = a warning,
# green #4ecca3 = nothing flagged, the title matching), none on Test Distribution and Raw Data; a coloured number only
# where it counts faults; tabs() prints "name:colour" per tab in page order ('-' = no dot)
tabs() { grep -o '<a class="nav-link[^>]*href="#tab-[a-z]*">[^<]*\(<span[^>]*>[^<]*</span>[^<]*\)*</a>' "$1" | while IFS= read -r l; do t=$(sed -E 's/.*href="#tab-([a-z]*)".*/\1/' <<<"$l"); c=$(grep -o 'tab-dot" style="background:#[0-9a-f]*' <<<"$l" | sed 's/.*background://'); printf '%s:%s ' "$t" "${c:--}"; done; echo; }
chk "tab dots (A4: Needs Repair = DOWN or CRITICAL NICs, Connection Health = any slow NIC): 14_ub and 14_un = connections amber, slow GREEN, temps green, nic green, distribution none, topology amber, checks red, all none; golden-C = green green RED green none green, clients green, checks red, all none; every dot's title matches its colour (3 pairs, 0 others; control: a planted mismatch counts 1); Needs Repair reads '(0)' plain at 0 on 14_ub" \
    "[ \"\$(tabs $W/ub.html)\" = 'connections:#ffc107 slow:#4ecca3 temps:#4ecca3 nic:#4ecca3 distribution:- topology:#ffc107 checks:#e94560 all:- ' ] && [ \"\$(tabs $W/un.html)\" = 'connections:#ffc107 slow:#4ecca3 temps:#4ecca3 nic:#4ecca3 distribution:- topology:#ffc107 checks:#e94560 all:- ' ] && [ \"\$(tabs $W/gc.html)\" = 'connections:#4ecca3 slow:#4ecca3 temps:#e94560 nic:#4ecca3 distribution:- topology:#4ecca3 clients:#4ecca3 checks:#e94560 all:- ' ] && [ \$(cat $W/ub.html $W/un.html $W/gc.html | grep -o 'background:#[0-9a-f]*;\" title=\"[^\"]*\"' | sort -u | grep -c -x -e 'background:#e94560;\" title=\"a fault to look at\"' -e 'background:#ffc107;\" title=\"a warning\"' -e 'background:#4ecca3;\" title=\"nothing flagged\"') = 3 ] && [ \$(cat $W/ub.html $W/un.html $W/gc.html | grep -o 'background:#[0-9a-f]*;\" title=\"[^\"]*\"' | sort -u | wc -l) = 3 ] && [ \$({ cat $W/ub.html; echo 'background:#e94560;\" title=\"a warning\"'; } | grep -o 'background:#[0-9a-f]*;\" title=\"[^\"]*\"' | sort -u | wc -l) = 4 ] && grep -q 'href=\"#tab-slow\">Needs Repair (0) <span class=\"tab-dot\"' $W/ub.html" \
    "ub: $(tabs $W/ub.html) | gc: $(tabs $W/gc.html) | titles: $(cat $W/ub.html $W/gc.html | grep -o 'background:#[0-9a-f]*;" title="[^"]*"' | sort -u | tr '\n' '|')"
# Needs Repair (A4): the repair set = NICs DOWN or CRITICAL; 14_ub and golden-C have none, so the header, the label
# and the card say 0 and the card body says so; 11 covers the non-empty case (11_xcrit: 2)
chk "Needs Repair at 0 (14_ub, golden-C): header '<b class=\"stat-good\">0</b> need repair |', label 'Needs Repair (0)' plain, card 'NICs that need repair — 0 (down, or CRITICAL: ...)' with 'No NIC needs repair.' in its body and no table (the heads are 11's, on the non-empty page); 0 'ran slow or are down' or 'need repair (&lt;' left (control: a planted old header counts 1)" \
    "( for f in $W/ub.html $W/gc.html; do grep -qF '<b class=\"stat-good\">0</b> need repair |' \$f && grep -q 'href=\"#tab-slow\">Needs Repair (0) <span class=\"tab-dot\"' \$f && grep -qF 'NICs that need repair — 0 (down, or CRITICAL: a run under the repair cut-off; worst first' \$f && grep -qF 'SLOW NICs that need no repair are in Connection Health' \$f && grep -qF 'No NIC needs repair.' \$f && [ \$(grep -c '<th>Worst column</th>' \$f) = 0 ] && [ \$(grep -c 'ran slow or are down\\|need repair (&lt;' \$f) = 0 ] || exit 1; done ) && [ \$({ cat $W/ub.html; echo '<b class=\"stat-bad\">3</b> ran slow or are down'; } | grep -c 'ran slow or are down') = 1 ]" \
    "$(grep -o '<b class=\"stat-[a-z]*\">[0-9]*</b> need repair' $W/ub.html | head -n 1) | $(grep -o 'NICs that need repair[^<]*' $W/ub.html | head -n 1 | cut -c1-80) | $(grep -c 'No NIC needs repair' $W/ub.html)"
# NIC, leaf and spine panels (criterion 4, commit C) through the page's own entry points: pageload_probe.js in its
# "panels" mode opens every NIC panel (window.topoNicPanel) and every node panel (window.topoShowPanel) over the page's
# own data and reads the drawer back; every cell present or '-', never undefined/NaN/empty; IP links titled with an onclick
node $S/fixtures/units/pageload_probe.js $W/ub.html panels > $W/pp.out 2>&1; pprc=$?
pj() { grep '^{"panels"' $W/pp.out | jq -r "$1"; }
chk "panels (14_ub): 4 NIC panels, each with a run table ('Backend runs, slowest first'), 12 IP links all titled with an onclick naming topoNicPanel; 2 leaf panels with 'Runs to the other leaves' and 'Declared' and 4 titled links; 2 host and 2 spine panels; 0 cells reading undefined/NaN/[object, 0 empty cells, 0 errors (control: the planted-error mode counts 1); window.topoNicPanel and topoShowPanel are functions" \
    "[ $pprc = 0 ] && [ \"\$(pj '[.panels.nic.n, .panels.nic.runs, .panels.nic.links, .panels.nic.linksOk, .panels.leaf.n, .panels.leaf.paths, .panels.leaf.declared, .panels.leaf.links, .panels.leaf.linksOk, .panels.host.n, .panels.spine.n] | join(\" \")')\" = '4 4 12 12 2 2 2 4 4 2 2' ] && [ \"\$(pj '[.panels[] | .bad, .empty] | add')\" = 0 ] && [ \"\$(pj '.panel_errors')\" = 0 ] && [ \"\$(grep '^{\"errors\"' $W/pp.out | jq -r '.fns.topoNicPanel + \" \" + .fns.topoShowPanel')\" = 'function function' ] && [ \"\$(node $S/fixtures/units/pageload_probe.js $W/ub.html planted | grep '^{\"errors\"' | jq '.errors | length')\" = 1 ]" \
    "rc=$pprc $(grep '^{\"panels\"' $W/pp.out | cut -c1-300)"
# criterion 4's addition (QA 10-29 17:54): an IP click opens the NIC panel without switching tabs; the probe's bootstrap.Tab
# stub records every .show() an IP click causes (0 wanted); and on a page whose Topology tab is NOT active at load (a copy
# with the active classes moved to Connection Health: the map never shown) the NIC panel still opens
sed 's/class="nav-link active" data-bs-toggle="tab" href="#tab-topology"/class="nav-link" data-bs-toggle="tab" href="#tab-topology"/; s/class="nav-link" data-bs-toggle="tab" href="#tab-connections"/class="nav-link active" data-bs-toggle="tab" href="#tab-connections"/; s/class="tab-pane fade show active" id="tab-topology"/class="tab-pane fade" id="tab-topology"/; s/class="tab-pane fade" id="tab-connections"/class="tab-pane fade show active" id="tab-connections"/' $W/ub.html > $W/ub_conn.html
node $S/fixtures/units/pageload_probe.js $W/ub_conn.html panels > $W/pp_conn.out 2>&1; pcrc=$?
chk "IP click keeps the tab: 0 bootstrap.Tab .show() calls caused by the 4 NIC-panel opens on 14_ub (control: the copy with Connection Health active at load holds 1 active <a>, Topology none); on that copy, where the map was never shown, the 4 NIC panels still open with 12 titled links and 0 errors" \
    "[ \"\$(pj '.panels.nic.tab_shows_by_ip_clicks')\" = 0 ] && [ \$(grep -c 'class=\"nav-link active\" data-bs-toggle=\"tab\" href=\"#tab-connections\"' $W/ub_conn.html) = 1 ] && [ \$(grep -c 'class=\"nav-link active\" data-bs-toggle=\"tab\" href=\"#tab-topology\"' $W/ub_conn.html) = 0 ] && [ $pcrc = 0 ] && [ \"\$(grep '^{\"panels\"' $W/pp_conn.out | jq -r '[.panels.nic.n, .panels.nic.linksOk, .panel_errors] | join(\" \")')\" = '4 12 0' ] && [ \"\$(grep '^{\"errors\"' $W/pp_conn.out | jq '.errors | length')\" = 0 ]" \
    "shows=$(pj '.panels.nic.tab_shows_by_ip_clicks') conn-copy: $(grep '^{\"panels\"' $W/pp_conn.out | cut -c1-200) $(grep '^{\"errors\"' $W/pp_conn.out | cut -c1-120)"
# hot-host ring (criterion 5, commit D): a host or client with a high or crit sensor carries hot: true, a #ff7a1a border
# of width 4 (highlight and hover too) and its speed colour as background; a legend line counts them (#legHot)
chk "hot-host ring: golden-C has 5 hot nodes (c1 c2 c4 h21 h22) with border #ff7a1a, borderWidth 4, highlight and hover borders #ff7a1a, and the legend line 'hot host (high / crit)' counting 5; 14_ub has 0 hot nodes, 0 nodes with a borderWidth key, legend 0 (control: golden-C's 5 non-hot nodes with a panel carry no borderWidth key either)" \
    "[ \"\$(nodes $W/gc.html | jq -c '[.[] | select(.hot == true) | .id] | sort')\" = '[\"c1\",\"c2\",\"c4\",\"h21\",\"h22\"]' ] && [ \$(nodes $W/gc.html | jq '[.[] | select(.hot == true) | select(.color.border == \"#ff7a1a\" and .borderWidth == 4 and .color.highlight.border == \"#ff7a1a\" and .color.hover.border == \"#ff7a1a\" and (.color.background | type) == \"string\")] | length') = 5 ] && [ \$(nodes $W/gc.html | jq '[.[] | select(.hot != true) | select(has(\"borderWidth\"))] | length') = 0 ] && grep -q '></span>hot host (high / crit): <b id=\"legHot\">5</b></div>' $W/gc.html && [ \$(nodes $W/ub.html | jq '[.[] | select(.hot == true)] | length') = 0 ] && [ \$(nodes $W/ub.html | jq '[.[] | select(has(\"borderWidth\"))] | length') = 0 ] && grep -q '>hot host (high / crit): <b id=\"legHot\">0</b></div>' $W/ub.html && [ \$(nodes $W/gc.html | jq '[.[] | select(.hot != true and .panel)] | length') -ge 5 ]" \
    "gc hot: $(nodes $W/gc.html | jq -c '[.[] | select(.hot == true) | .id]') legend: $(grep -o 'hot host (high / crit): <b id=\"legHot\">[0-9]*' $W/gc.html | head -n 1); ub borderWidth keys: $(nodes $W/ub.html | jq '[.[] | select(has("borderWidth"))] | length')"
# "Where to look" edges (10-29, the scope after the demo round): 14_where (five hosts, h1 hot to crit, rail B at 100G
# = CRITICAL, four clients at 50G, h4 without LLDP) and 14_clean (two hosts, nothing wrong), both made by mkbundles.sh
python3 $P $X/14_where.tgz $W/uw.html > $W/uw.pout 2>&1; uwrc=$?
python3 $P $X/14_clean.tgz $W/uc.html > $W/uc.pout 2>&1; ucrc=$?
first=$(wlines $W/uw.html | head -n 1)
chk "where to look (14_where): the heat-and-slow line comes first: chip 'where-sev s0' reading 'HEAT + SLOW', text 'h1: cpu NNNC (crit...) and N NIC(s) slow. Check heat before the fabric.' (the flag reads crit+rise: the fake's CPU climbs through the run; control: the copy whose first chip reads s1 fails the same predicate)" \
    "{ [ $uwrc = 0 ] || [ $uwrc = 3 ]; } && [ \$(grep -c 'where-sev s0\">HEAT + SLOW</span>' <<<\"\$first\") = 1 ] && grep -q -E 'where-text\">h1: cpu [0-9.]+C \(crit[+)].* and [0-9]+ NIC\(s\) slow\. Check heat before the fabric\.</span>' <<<\"\$first\" && [ \$(sed 's/where-sev s0/where-sev s1/' <<<\"\$first\" | grep -c 'where-sev s0\">HEAT + SLOW</span>') = 0 ]" \
    "rc=$uwrc first: $(sed 's/<[^>]*>//g' <<<"$first" | cut -c1-160)"
many=$(wlines $W/uw.html | grep 'NICs ran slow or are down (')
chk "where to look (14_where): more than 5 slow NICs on cool hosts collapse to ONE line ('N NICs ran slow or are down (...); worst: a, b, c of expected.', N >= 6, the worst list 3 long) and no per-NIC slow line ('% of expected at worst.') is left; control: a planted per-NIC line counts 1" \
    "[ \$(grep -c '' <<<\"\$many\") = 1 ] && [ \$(grep -o 'where-text\">[0-9]* NICs ran slow' <<<\"\$many\" | grep -o '[0-9]*') -ge 6 ] && [ \$(sed 's/.*; worst: //; s/ of expected\..*//' <<<\"\$many\" | awk -F', ' '{print NF}') = 3 ] && [ \$(wlines $W/uw.html | grep -c '% of expected at worst\.') = 0 ] && [ \$({ wlines $W/uw.html; echo 'x (leaf1): 100 Gbps, 25% of expected at worst.'; } | grep -c '% of expected at worst\.') = 1 ]" \
    "lines $(wn $W/uw.html): $(sed 's/<[^>]*>//g' <<<"$many" | cut -c1-200)"
node $S/fixtures/units/pageload_probe.js $W/uw.html panels > $W/pw.out 2>&1; pwrc=$?
perl -pe 's#(<p class="text-success mb-0">No NIC needs repair\.</p>)#$1<table><tr><td><details><summary>1 x</summary><a class="ip-link" onclick="topoNicPanel(\x27198.18.0.99\x27); return false;">198.18.0.99</a></details></td></tr></table>#' $W/ub.html > $W/ub_det.html
node $S/fixtures/units/pageload_probe.js $W/ub_det.html panels > $W/pw_det.out 2>&1
pw() { grep '^{"panels"' "$1" | jq -r "$2"; }
chk "Needs Repair (14_where, 11 need repair): the repair NICs with no switch seen sit in three grouped <details> rows, one per role and status: '3 client NICs: no switch seen, critical', '1 backend NICs: no switch seen, down (not cabled or not in use?)' and '1 backend NICs: no switch seen, critical(cross)' (h4 without LLDP: its B NIC reads DOWN, its A NIC only failed the cross-rail run); the probe opens every IP link inside <details> rows: 5 links, all titled, 0 'No NIC row', 0 errors (control: a planted row on 14_ub with an IP the run never saw counts 1 'No NIC row')" \
    "[ \$(grep -c '<details><summary>3 client NICs: no switch seen, critical</summary>' $W/uw.html) = 1 ] && [ \$(grep -c '<details><summary>1 backend NICs: no switch seen, down (not cabled or not in use?)</summary>' $W/uw.html) = 1 ] && [ \$(grep -c '<details><summary>1 backend NICs: no switch seen, critical(cross)</summary>' $W/uw.html) = 1 ] && [ \$(grep -o '<details><summary>' $W/uw.html | wc -l | tr -d ' ') = 3 ] && grep -q 'NICs that need repair — 11 (' $W/uw.html && [ $pwrc = 0 ] && [ \"\$(pw $W/pw.out '[.panels.details.ips, .panels.details.titled, .panels.details.norow, .panels.details.errors, .panel_errors] | join(\" \")')\" = '5 5 0 0 0' ] && [ \"\$(pw $W/pw_det.out '[.panels.details.ips, .panels.details.norow] | join(\" \")')\" = '1 1' ]" \
    "rc=$pwrc details: $(pw $W/pw.out '.panels.details' | tr -d '\n') planted: $(pw $W/pw_det.out '.panels.details' | tr -d '\n') summary: $(grep -o '<details><summary>[^<]*' $W/uw.html | head -n 2 | tr '\n' '|')"
chk "where to look (14_clean): no finding, so the card is the calm one ('card mb-3 where calm', chip CLEAN, 'Nothing to look at first.', no where-list), 0 need repair and no red or amber tab dot (control: 14_ub has 0 'Nothing to look at first.' and 1 where-list)" \
    "[ $ucrc = 0 ] || [ $ucrc = 3 ] && [ \$(grep -c 'card mb-3 where calm' $W/uc.html) = 1 ] && [ \$(grep -c 'where-sev ok\">CLEAN</span> Nothing to look at first\.' $W/uc.html) = 1 ] && [ \$(grep -c 'where-list' $W/uc.html) = 0 ] && grep -qF '<b class=\"stat-good\">0</b> need repair |' $W/uc.html && [ \$(tabs $W/uc.html | tr ' ' '\\n' | grep -c -e '#e94560' -e '#ffc107') = 0 ] && [ \$(tabs $W/uc.html | tr ' ' '\\n' | grep -c '#4ecca3') -ge 3 ] && [ \$(grep -c 'Nothing to look at first\.' $W/ub.html) = 0 ] && [ \$(grep -c 'where-list' $W/ub.html) = 1 ]" \
    "rc=$ucrc tabs: $(tabs $W/uc.html) card: $(grep -o 'where-sev ok[^<]*' $W/uc.html | head -n 1) $(tail -n 2 $W/uc.pout | cut -c1-120 | tr '\n' '|')"
# the ring after the map's own calls: resetTopo() and topoSetLayout('force') update the nodes in place and must not strip
