node $S/fixtures/units/pageload_probe.js $W/gc.html ring > $W/pr.out 2>&1; prrc=$?
sed -E 's/"borderWidth": ?4/"borderWidth": 3/' $W/gc.html > $W/gc_ring.html   # one node's ring width off: the control
node $S/fixtures/units/pageload_probe.js $W/gc_ring.html ring > $W/pr_ctl.out 2>&1
chk "hot-host ring survives the map's own calls (golden-C): 5 hot nodes ringed at load, still 5 after resetTopo() and after topoSetLayout('force'), 0 errors (control: the copy with one node's borderWidth at 3 counts 4 at load)" \
    "[ $prrc = 0 ] && [ \"\$(grep '^{\"ring\"' $W/pr.out | jq -r '[.ring.hot, .ring.load, .ring.reset, .ring.force, .ring_errors] | join(\" \")')\" = '5 5 5 5 0' ] && [ \"\$(grep '^{\"ring\"' $W/pr_ctl.out | jq -r '[.ring.hot, .ring.load] | join(\" \")')\" = '5 4' ]" \
    "rc=$prrc $(grep '^{"ring"' $W/pr.out) control: $(grep '^{"ring"' $W/pr_ctl.out)"
out=$($B $H/test_uplink.sh $C $W/tus span 2>&1)
chk "uplink awk: a rail spread over two leaves counts its same-rail runs between them" "grep -q '^  Uplinks leafa.example phase 1: out 4.62 T / in 0.0 G of 6.40 T declared (72%)' <<<\"\$out\" && grep -q '^  Uplinks leafc.example phase 1: out 0.0 G / in 4.62 T' <<<\"\$out\" && grep -q '^  Uplinks leafb.example phase 2: out 0.0 G / in 6.28 T of 6.40 T declared (98%)' <<<\"\$out\" && grep -q '^  Uplinks leafa.example phase 2: out 3.14 T' <<<\"\$out\"" "$out"
finish
